    j.extend(a, &[11], &mut Run).unwrap();
    let before = j.stats();
    // Calls the real Vec::try_reserve_exact, which rejects an object larger
    // than isize::MAX. This is capacity failure, NOT injected global OOM.
    assert_eq!(
